#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef char E;

typedef struct ListNode {
    E ele;
    struct ListNode *prev;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();
void addLast_LinkedList(LinkedList *link, E ele);
E removeLast_LinkedList(LinkedList *link);
E getLast_LinkedList(LinkedList* link);

int main() {
    char s[100];
    gets(s);

    int count = 0;
    LinkedList *stack = new_LinkedList();

    for (int i = 0; i < strlen(s); i++) {
        if(s[i] != ')' && s[i] != '(') continue;

        if(stack->size > 0 && s[i] == ')') {
            if(getLast_LinkedList(stack) == '(') {
                removeLast_LinkedList(stack);
                count++;
                continue;
            }

            puts("-1");
            return 0;
        }

        addLast_LinkedList(stack,s[i]);
    }

    if(stack->size > 0) {
        puts("-1");
    } else {
        printf("%d\n", count);
    }

    return 0;
}

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, E ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->prev = NULL;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        node->prev = link->tail;
        link->tail = node;
    }

    link->size++;
}

E removeLast_LinkedList(LinkedList *link) {
    if (link->size == 0) exit(-1);

    ListNode *removed = link->tail;

    if (link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->tail = link->tail->prev;
        link->tail->next = NULL;
    }

    link->size--;

    E res = removed->ele;

    free(removed);

    return res;
}

E getLast_LinkedList(LinkedList* link) {
    if(link->size == 0) exit(-1);
    return link->tail->ele;
}
